sources.content:
resource "aws_emr_studio" "dev_studio" {
  auth_mode                   = "IAM"
  default_s3_location         = "s3://${aws_s3_bucket.emr_studio_bucket.bucket}/logs"
  engine_security_group_id    = aws_security_group.emr_security_group.id
  name                        = "${var.app}-${var.stage_name}-studio"
  service_role                = aws_iam_role.emr_studio_role.arn
  subnet_ids                  = [aws_subnet.emr_public_subnet1.id]
  vpc_id                      = aws_vpc.emr_vpc.id
  workspace_security_group_id = aws_security_group.emr_security_group.id
  tags = {
    Application = var.app
    Environment = var.stage_name
  }
}


resource "aws_emrserverless_application" "emr_serverless" {
  name          = "${var.app}-${var.stage_name}-emr-${data.aws_caller_identity.current.account_id}"
  release_label = "emr-6.9.0"
  type          = "spark"

  initial_capacity {
    initial_capacity_type = "Driver"

    initial_capacity_config {
      worker_count = 5
      worker_configuration {
        cpu    = "4 vCPU"
        memory = "20 GB"
      }
    }
  }

  initial_capacity {
    initial_capacity_type = "Executor"

    initial_capacity_config {
      worker_count = 5
      worker_configuration {
        cpu    = "4 vCPU"
        memory = "20 GB"
      }
    }
  }

  maximum_capacity {
    cpu    = "150 vCPU"
    memory = "1000 GB"
  }

  tags = {
    Name        = "EMR Serverless Application"
    Environment = var.stage_name
    Application = var.app
  }
}

data "aws_iam_policy_document" "emr_s3_and_glue_inline_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["emr-serverless.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_serverless_role" {
  name               = "${var.app}-${var.stage_name}-emr-serverless-role"
  assume_role_policy = data.aws_iam_policy_document.emr_s3_and_glue_inline_policy.json
  tags = {
    Name        = ""
    Environment = var.stage_name
    Application = var.app
  }
}

data "aws_iam_policy_document" "lambda_emr_sfn_start_job_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com", "preprod.states.aws.internal"]
    }
  }
}


resource "aws_iam_role" "lambda_emr_sfn_start_job_role" {
  name               = "${var.app}-${var.stage_name}-sfn-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_emr_sfn_start_job_policy.json
  tags = {
    Name        = ""
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_iam_role_policy" "clicklogger_emr_sfn_start_job_inline_policy" {
  name   = "${var.app}-${var.stage_name}-emr-job-inline_policy"
  role   = aws_iam_role.lambda_emr_sfn_start_job_role.id
  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "EMRStudioCreate",
            "Effect": "Allow",
            "Action": [
                "elasticmapreduce:CreateStudioPresignedUrl",
                "elasticmapreduce:DescribeStudio",
                "elasticmapreduce:CreateStudio",
                "elasticmapreduce:ListStudios"
            ],
            "Resource": "*"
        },
        {
            "Sid": "EMRServerlessFullAccess",
            "Effect": "Allow",
            "Action": [
                "emr-serverless:*"
            ],
            "Resource": "*"
        },
        {
            "Sid": "AllowEC2ENICreationWithEMRTags",
            "Effect": "Allow",
            "Action": [
                "ec2:CreateNetworkInterface"
            ],
            "Resource": [
                "arn:aws:ec2:*:*:network-interface/*"
            ],
            "Condition": {
                "StringEquals": {
                    "aws:CalledViaLast": "ops.emr-serverless.amazonaws.com"
                }
            }
        },
        {
            "Sid": "AllowEMRServerlessServiceLinkedRoleCreation",
            "Effect": "Allow",
            "Action": "iam:CreateServiceLinkedRole",
            "Resource": "arn:aws:iam::*:role/aws-service-role/*"
        },
        {
            "Effect": "Allow",
            "Action": "iam:PassRole",
            "Resource": "*"
        }
    ]
}
EOF
}

data "aws_iam_policy_document" "emr_studio_policy_doc" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "click_logger_emr_serverless_inline_policy" {
  name   = "${var.app}-${var.stage_name}-emr-s3-glue-inline_policy"
  role   = aws_iam_role.emr_serverless_role.id
  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "ReadAccessForEMRSamples",
            "Effect": "Allow",
            "Action": [
                "s3:GetObject",
                "s3:ListBucket"
            ],
            "Resource": [
                "arn:aws:s3:::*.elasticmapreduce",
                "arn:aws:s3:::*.elasticmapreduce/*"
            ]
        },
        {
            "Sid": "FullAccessToOutputBucket",
            "Effect": "Allow",
            "Action": [
                "s3:PutObject",
                "s3:GetObject",
                "s3:ListBucket",
                "s3:DeleteObject"
            ],
            "Resource": [
                "${aws_s3_bucket.emr_studio_bucket.arn}",
                "${aws_s3_bucket.emr_studio_bucket.arn}/*",
                "${aws_s3_bucket.job_source_s3_bucket.arn}",
                "${aws_s3_bucket.job_source_s3_bucket.arn}/*",
                "${aws_s3_bucket.output_s3_bucket.arn}",
                "${aws_s3_bucket.output_s3_bucket.arn}/*"
            ]
        },
        {
            "Sid": "GlueCreateAndReadDataCatalog",
            "Effect": "Allow",
            "Action": [
                "glue:GetDatabase",
                "glue:CreateDatabase",
                "glue:GetDataBases",
                "glue:CreateTable",
                "glue:GetTable",
                "glue:UpdateTable",
                "glue:DeleteTable",
                "glue:GetTables",
                "glue:GetPartition",
                "glue:GetPartitions",
                "glue:CreatePartition",
                "glue:BatchCreatePartition",
                "glue:GetUserDefinedFunctions"
            ],
            "Resource": ["*"]
        }
    ]
}
EOF
}


resource "aws_iam_role" "emr_studio_role" {
  name               = "${var.app}-${var.stage_name}-emr-studio-role"
  assume_role_policy = data.aws_iam_policy_document.emr_studio_policy_doc.json
  tags = {
    Name        = ""
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_iam_role_policy" "emr_studio_policy" {
  name   = "${var.app}-${var.stage_name}-emr-studio-policy"
  role   = aws_iam_role.emr_studio_role.id
  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Resource": "*",
            "Action": [
                "ec2:AuthorizeSecurityGroupEgress",
                "ec2:AuthorizeSecurityGroupIngress",
                "ec2:CancelSpotInstanceRequests",
                "ec2:CreateFleet",
                "ec2:CreateLaunchTemplate",
                "ec2:CreateNetworkInterface",
                "ec2:CreateSecurityGroup",
                "ec2:CreateTags",
                "ec2:DeleteLaunchTemplate",
                "ec2:DeleteNetworkInterface",
                "ec2:DeleteSecurityGroup",
                "ec2:DeleteTags",
                "ec2:DescribeAvailabilityZones",
                "ec2:DescribeAccountAttributes",
                "ec2:DescribeDhcpOptions",
                "ec2:DescribeImages",
                "ec2:DescribeInstanceStatus",
                "ec2:DescribeInstances",
                "ec2:DescribeKeyPairs",
                "ec2:DescribeLaunchTemplates",
                "ec2:DescribeNetworkAcls",
                "ec2:DescribeNetworkInterfaces",
                "ec2:DescribePrefixLists",
                "ec2:DescribeRouteTables",
                "ec2:DescribeSecurityGroups",
                "ec2:DescribeSpotInstanceRequests",
                "ec2:DescribeSpotPriceHistory",
                "ec2:DescribeSubnets",
                "ec2:DescribeTags",
                "ec2:DescribeVpcAttribute",
                "ec2:DescribeVpcEndpoints",
                "ec2:DescribeVpcEndpointServices",
                "ec2:DescribeVpcs",
                "ec2:DetachNetworkInterface",
                "ec2:ModifyImageAttribute",
                "ec2:ModifyInstanceAttribute",
                "ec2:RequestSpotInstances",
                "ec2:RevokeSecurityGroupEgress",
                "ec2:RunInstances",
                "ec2:TerminateInstances",
                "ec2:DeleteVolume",
                "ec2:DescribeVolumeStatus",
                "ec2:DescribeVolumes",
                "ec2:DetachVolume",
                "iam:GetRole",
                "iam:GetRolePolicy",
                "iam:ListInstanceProfiles",
                "iam:ListRolePolicies",
                "iam:PassRole",
                "sdb:BatchPutAttributes",
                "sdb:Select",
                "sqs:CreateQueue",
                "sqs:Delete*",
                "sqs:GetQueue*",
                "sqs:PurgeQueue",
                "sqs:ReceiveMessage",
                "cloudwatch:PutMetricAlarm",
                "cloudwatch:DescribeAlarms",
                "cloudwatch:DeleteAlarms",
                "application-autoscaling:RegisterScalableTarget",
                "application-autoscaling:DeregisterScalableTarget",
                "application-autoscaling:PutScalingPolicy",
                "application-autoscaling:DeleteScalingPolicy",
                "application-autoscaling:Describe*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
                "s3:GetEncryptionConfiguration",
                "s3:GetObject",
                "s3:ListBucket",
                "s3:PutObject*",
                "s3:DeleteObject"
            ],
            "Resource": [
                "${aws_s3_bucket.emr_studio_bucket.arn}",
                "${aws_s3_bucket.emr_studio_bucket.arn}/*",
                "${aws_s3_bucket.job_source_s3_bucket.arn}",
                "${aws_s3_bucket.job_source_s3_bucket.arn}/*",
                "${aws_s3_bucket.output_s3_bucket.arn}",
                "${aws_s3_bucket.output_s3_bucket.arn}/*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": "iam:CreateServiceLinkedRole",
            "Resource": "arn:aws:iam::*:role/aws-service-role/spot.amazonaws.com/AWSServiceRoleForEC2Spot*",
            "Condition": {
                "StringLike": {
                    "iam:AWSServiceName": "spot.amazonaws.com"
                }
            }
        }
    ]
}
EOF
}

resource "aws_s3_bucket" "emr_studio_bucket" {
  bucket = "${data.aws_region.current.region}-${var.app}-${var.stage_name}-emr-studio-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name        = "EMR studio bucket"
    Application = var.app
    Environment = var.stage_name
  }
}

resource "aws_s3_bucket" "output_s3_bucket" {
  bucket = "${data.aws_region.current.region}-${var.app}-${var.stage_name}-output-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name        = "EMR Job Output S3 bucket"
    Application = var.app
    Environment = var.stage_name
  }
}

resource "aws_s3_bucket" "job_source_s3_bucket" {
  bucket = "${data.aws_region.current.region}-${var.app}-${var.stage_name}-source-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name        = "EMR Job Source (eg. jar file) S3 bucket"
    Application = var.app
    Environment = var.stage_name
  }
}

resource "aws_sfn_state_machine" "sfn_state_machine" {
  name     = "${var.app}-${var.stage_name}-state-machine"
  role_arn = aws_iam_role.lambda_emr_sfn_start_job_role.arn
  tags = {
    Name        = "State Machine"
    Environment = var.stage_name
    Application = var.app
  }

  definition = <<EOF
{
  "Comment": "Workflow to trigger an EMR Serverless Job.",
  "StartAt": "StartEMRServerlessJob",
  "States": {
    "StartEMRServerlessJob": {
     "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:emrserverless:startJobRun",
      "ResultPath": "$.Job.Input",
      "Next": "GetJobStatus",
      "Parameters": {
        "ApplicationId": "${aws_emrserverless_application.emr_serverless.id}",
        "ClientToken.$": "States.UUID()",
        "Name": "${aws_emrserverless_application.emr_serverless.name}",
        "ExecutionRoleArn": "${aws_iam_role.emr_serverless_role.arn}",
        "JobDriver": {
          "SparkSubmit": {
            "EntryPoint": "s3://${aws_s3_bucket.job_source_s3_bucket.id}/${var.jar_name}",
            "EntryPointArguments.$": "States.Array($.InputDate, 'us-east-1-clicklogger-dev-firehose-delivery-078876706719', 'us-east-1-pattern-sfn-emrserverless-dev-output-078876706719')",
            "SparkSubmitParameters": "--class com.examples.clicklogger.Loggregator"
          }
        }
     }
    },
    "GetJobStatus": {
        "Next": "CheckJobSuccess",
        "Type": "Task",
        "ResultPath": "$.Job.Status",
        "Resource": "arn:aws:states:::aws-sdk:emrserverless:getJobRun",
        "Parameters": {
          "ApplicationId": "${aws_emrserverless_application.emr_serverless.id}",
          "JobRunId.$": "$.Job.Input.JobRunId"
        }
      },
      "Wait": {
        "Type": "Wait",
        "Seconds": 20,
        "Next": "GetJobStatus"
      },
      "CheckJobSuccess": {
        "Type": "Choice",
        "Choices": [
          {
            "And": [
              {
                "Variable": "$.Job.Status",
                "IsPresent": true
              },
              {
                "Or": [
                  {
                    "Variable": "$.Job.Status.JobRun.State",
                    "StringEquals": "SUCCESS"
                  }
                ]
              }
            ],
            "Next": "Success"
          }
        ],
        "Default": "CheckJobFailure"
      },
      "CheckJobFailure": {
        "Type": "Choice",
        "Choices": [
          {
            "And": [
              {
                "Variable": "$.Job.Status",
                "IsPresent": true
              },
              {
                "Or": [
                  {
                    "Variable": "$.Job.Status.JobRun.State",
                    "StringEquals": "CANCELLED"
                  },
                  {
                    "Variable": "$.Job.Status.JobRun.State",
                    "StringEquals": "FAILED"
                  }
                ]
              }
            ],
            "Next": "Failure"
          }
        ],
        "Default": "Wait"
      },
      "Failure": {
        "Type": "Fail"
      },
      "Success": {
        "Type": "Succeed"
      }
    }
}
EOF
}

variable "app" {
  description = "Application prefix for the AWS services that are built"
}

variable "stage_name" {
}
variable "jar_name" {

}

resource "aws_vpc" "emr_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "${var.app}-${var.stage_name}-VPC"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_subnet" "emr_public_subnet1" {
  vpc_id     = aws_vpc.emr_vpc.id
  cidr_block = "10.0.0.0/24"

  tags = {
    Name = "${var.app}-${var.stage_name}-public-subnet1"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_subnet" "emr_private_subnet1" {
  vpc_id     = aws_vpc.emr_vpc.id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "${var.app}-${var.stage_name}-private-subnet1"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_internet_gateway" "emr_igw" {
  vpc_id = aws_vpc.emr_vpc.id
    tags = {
    Name = "${var.app}-${var.stage_name}-igw"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_route_table" "emr_route_table" {
  vpc_id = aws_vpc.emr_vpc.id
    tags = {
    Name = "${var.app}-${var.stage_name}-route-tbl"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_route" "emr_public_route" {
  route_table_id         = aws_route_table.emr_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.emr_igw.id
}

resource "aws_route_table_association" "emr_route_table_association1" {
  subnet_id      = aws_subnet.emr_public_subnet1.id
  route_table_id = aws_route_table.emr_route_table.id
}

resource "aws_eip" "emr_ip" {
  domain = "vpc"

  tags = {
    Name = "${var.app}-${var.stage_name}-elastic-ip"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_nat_gateway" "emr_ngw" {
  allocation_id = aws_eip.emr_ip.id
  subnet_id     = aws_subnet.emr_public_subnet1.id

  tags = {
    Name = "${var.app}-${var.stage_name}-nat-gw"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_route_table" "emr_ngw_route_table" {
  vpc_id = aws_vpc.emr_vpc.id
}

resource "aws_route" "emr_ngw_route" {
  route_table_id         = aws_route_table.emr_ngw_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.emr_ngw.id
}

resource "aws_route_table_association" "emr_ngw_route_table_association1" {
  subnet_id      = aws_subnet.emr_private_subnet1.id
  route_table_id = aws_route_table.emr_ngw_route_table.id
}

resource "aws_route_table" "emr_vpce_route_table" {
  vpc_id = aws_vpc.emr_vpc.id
}

resource "aws_route" "emr_vpce_route" {
  route_table_id         = aws_route_table.emr_vpce_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.emr_ngw.id
}

resource "aws_security_group" "emr_security_group" {
  name        = "${var.app}-${var.stage_name}-sg"
  description = "Allowed Ports"
  vpc_id      = aws_vpc.emr_vpc.id
    tags = {
    Name = "${var.app}-${var.stage_name}-sg"
    Environment = var.stage_name
    Application = var.app
  }
}

resource "aws_security_group_rule" "emr_security_group_rule" {
  type              = "egress"
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.emr_security_group.id
}
